/**
 * Resolve the PNG generated by a unified portfolio step (not the original reference).
 */

import { existsSync } from "node:fs";
import { join as pathJoin } from "node:path";
import { FIGMA_SCREEN_DIFFS_DIR } from "./figma-screen-portfolio.mjs";

export function safeStorySegment(input) {
  return String(input)
    .trim()
    .replace(/[<>:"/\\|?*\u0000-\u001F]/g, "-")
    .replace(/\s+/g, "-")
    .replace(/-+/g, "-");
}

export function toRepoPreviewPath(repoRoot, absPath) {
  if (!absPath || typeof absPath !== "string") return null;
  const normalized = absPath.replace(/\\/g, "/");
  const repo = repoRoot.replace(/\\/g, "/");
  if (normalized.startsWith(repo)) {
    return `/repo/${normalized.slice(repo.length).replace(/^\//, "")}`;
  }
  return null;
}

/** @param {string} stepId @param {"figma"|"storybook"|undefined} entryPoint */
function generatedFieldOrder(stepId, entryPoint) {
  if (stepId === "structural") {
    return entryPoint === "figma" ? [] : ["renderedPng", "targetPng"];
  }
  if (stepId === "vsFigmaLive") return ["targetPng", "figmaPng", "renderedPng"];
  if (stepId === "vsStorybook") return ["targetPng", "renderedPng"];
  if (stepId === "vsReactHtml") return ["targetPng", "renderedPng", "figmaPng"];
  if (stepId === "vsReactTsx") return ["targetPng", "renderedPng"];
  return [];
}

/** Prefer *-raw.png gate artifacts over legacy composited paths. */
function rawParityLegPath(parityBase, leg) {
  const raw = pathJoin(parityBase, `${leg}-raw.png`);
  const main = pathJoin(parityBase, `${leg}.png`);
  if (existsSync(raw)) return raw;
  if (existsSync(main)) return main;
  return null;
}

/**
 * @param {string} repoRoot
 * @param {string} stepId
 * @param {"figma"|"storybook"|undefined} entryPoint
 * @param {string} storyId
 */
function fallbackGeneratedPaths(repoRoot, stepId, entryPoint, storyId) {
  const seg = safeStorySegment(storyId);
  const paths = [];

  if (entryPoint === "figma") {
    const parityBase = pathJoin(repoRoot, FIGMA_SCREEN_DIFFS_DIR, seg, "originalParity");
    if (stepId === "vsFigmaLive") {
      const raw = rawParityLegPath(parityBase, "figmaLive");
      if (raw) paths.push(raw);
    } else if (stepId === "vsStorybook") {
      const raw = rawParityLegPath(parityBase, "storybook");
      if (raw) paths.push(raw);
    } else if (stepId === "vsReactHtml") {
      const raw = rawParityLegPath(parityBase, "reactHtml");
      if (raw) paths.push(raw);
    } else if (stepId === "vsReactTsx") {
      const raw = rawParityLegPath(parityBase, "reactTsx");
      if (raw) paths.push(raw);
    }
    return paths;
  }

  const suiteDirs = {
    structural: ["pixel-diffs"],
    vsFigmaLive: ["figma-live-diffs"],
    vsStorybook: ["storybook-parity-diffs"],
    vsReactHtml: ["delivery-diffs", "storybook-parity-diffs"],
    vsReactTsx: ["delivery-diffs", "storybook-parity-diffs"]
  };
  const renderedNames = {
    structural: "rendered.png",
    vsFigmaLive: "figma.png",
    vsStorybook: "storybook.png",
    vsReactHtml: "figma.png",
    vsReactTsx: "figma.png"
  };

  const dirs = suiteDirs[stepId] ?? [];
  const file = renderedNames[stepId];
  if (!file) return paths;

  for (const dir of dirs) {
    paths.push(pathJoin(repoRoot, dir, seg, file));
    paths.push(pathJoin(repoRoot, dir, "by-story", seg, file));
    if (stepId === "vsStorybook" || stepId === "vsReactHtml" || stepId === "vsReactTsx") {
      paths.push(pathJoin(repoRoot, dir, "by-story", seg, stepId, file));
    }
  }

  return paths;
}

/**
 * @param {string} repoRoot
 * @param {{ stepId: string, entryPoint?: "figma"|"storybook", storyId: string, rec?: object | null, status?: string }} opts
 */
export function resolveStepGeneratedPreviewUrl(repoRoot, opts) {
  const { stepId, entryPoint, storyId, rec, status } = opts;
  if (status === "not_tested" || status === "skipped") return null;

  for (const field of generatedFieldOrder(stepId, entryPoint)) {
    const candidate = rec?.[field];
    if (candidate && existsSync(candidate)) {
      return toRepoPreviewPath(repoRoot, candidate);
    }
  }

  for (const candidate of fallbackGeneratedPaths(repoRoot, stepId, entryPoint, storyId)) {
    if (existsSync(candidate)) {
      return toRepoPreviewPath(repoRoot, candidate);
    }
  }

  return null;
}

/**
 * @param {object} cell
 * @param {string} repoRoot
 * @param {{ stepId: string, entryPoint?: "figma"|"storybook", storyId: string, rec?: object | null }} ctx
 */
export function attachStepPreviewUrl(cell, repoRoot, ctx) {
  const previewUrl = resolveStepGeneratedPreviewUrl(repoRoot, {
    ...ctx,
    status: cell?.status
  });
  return previewUrl ? { ...cell, previewUrl } : cell;
}
